import type { Feature } from '../agents/types.js'

/**
 * Perform a topological sort of the feature list respecting dependsOn edges.
 *
 * Returns features in an order where every feature appears after all its
 * dependencies.  Features with no dependsOn are returned first, sorted by
 * their original priority order within each level.
 *
 * Throws if the dependency graph contains a cycle (calls validateAcyclic
 * internally).
 */
export function topologicalSort(features: Feature[]): Feature[] {
  validateAcyclic(features)

  const byId = new Map(features.map(f => [f.id, f]))
  const result: Feature[] = []
  const visited = new Set<string>()

  function visit(id: string, ancestors: Set<string>): void {
    if (visited.has(id)) return
    const feature = byId.get(id)
    if (!feature) return // unknown dep id — skip gracefully

    for (const depId of feature.dependsOn ?? []) {
      visit(depId, ancestors)
    }
    visited.add(id)
    result.push(feature)
  }

  // Process in original order so stable sort within each level
  for (const f of features) {
    visit(f.id, new Set())
  }

  return result
}

