async run(): Promise<void> {
  const { projectDir, maxFeatures, dryRun, concurrency } = this.opts
  const runStart = Date.now()

  initEventLog(projectDir)

  // Validate dependency graph is acyclic before doing any work
  const featuresDataForValidation = await readFeaturesFile(projectDir)
  validateAcyclic(featuresDataForValidation.features)

  if (concurrency > 1) {
    await this.runParallel()
    return
  }

